  const path=join(directory,name+'.mjs');writeFileSync(path,relocated);assert.equal(readFileSync(path,'utf8'),relocated);sides[name]=await import(pathToFileURL(path).href);retain('complete-'+name+'-producer-source-adapter',{actual,currentBody,oldBody,source,restored,appended,relocated,edits,inverse,scope:'Test-only complete module with the actual private helper exported; no production export or origin authority.'});
