test('already aligned full deltas keep the complete original object and mandatory native Hash tape',async(t,retain)=>{
 const api=await modules(t,retain);
 for(const [left,right]of [['pub fn one()->u8{1}','pub fn two()->u8{2}'],['pub const N:u8=1;\n','pub const N:u8=2;\n'],['pub fn a()->u8{0}','pub fn a()->u8{0}']]){
  const before=cst(left),after=cst(right),old=hashes(()=>api.before.testStaticDelta(before,after)),current=hashes(()=>api.current.testStaticDelta(before,after));assert.ok(old.value.edit.span.every(at=>before.boundaries.includes(at)));assert.ok(old.value.inverse.span.every(at=>after.boundaries.includes(at)));assert.deepEqual(current,old);retain('complete-old-valid-object-and-native-tape',{old,current,checked:verify(current.value,before,after)});
 }
});
test('identifier extension moves the common start to independently expected boundaries on both CSTs',async(t,retain)=>{
 const api=await modules(t,retain),before=cst('pub fn a()->u8{0}'),after=cst('pub fn ab()->u8{0}'),old=api.before.testStaticDelta(before,after),current=api.current.testStaticDelta(before,after);
 assert.equal(before.source.indexOf('a('),7);assert.deepEqual(current.edit,{span:[7,8],expected:'a',replacement:'ab'});assert.deepEqual(current.inverse,{span:[7,9],expected:'ab',replacement:'a'});assert.ok(old.inverse.span.some(at=>!after.boundaries.includes(at)));retain('complete-identifier-endpoint-regression',{old,checked:verify(current,before,after)});
});
test('joining punctuators expands the suffix end as well as the shared start without splitting tokens',async(t,retain)=>{
 const api=await modules(t,retain),left='pub fn checked(a:bool,b:bool)->bool{a & &b}',right='pub fn checked(a:bool,b:bool)->bool{a &&b}',before=cst(left),after=cst(right),old=api.before.testStaticDelta(before,after),current=api.current.testStaticDelta(before,after),start=left.indexOf('& &');
 assert.deepEqual(current.edit,{span:[start,start+3],expected:'& &',replacement:'&&'});assert.deepEqual(current.inverse,{span:[start,start+2],expected:'&&',replacement:'& &'});assert.equal(after.boundaries.includes(old.inverse.span[1]),false);retain('complete-punctuation-endpoint-regression',{old,checked:verify(current,before,after)});
});
