 assert.deepEqual(api.current.testStaticDelta(before,after),valid);assert.deepEqual(Object.keys(valid),['edit','inverse','trace','afterCanonicalSha256','completeInverse','meaning']);retain('complete-refusal-and-recovery-data',{before,after,valid,forged,wrong,scope:'Data-only exact span checks; no public metadata grants semantic source authority.'});
